import zlib,re
data=open('documents/notice_of_commencement_and_bar_date.pdf','rb').read()
for m in re.finditer(rb'stream\r?\n(.*?)endstream', data, re.S):
    try:
        t=zlib.decompress(m.group(1))
        txt=re.sub(rb'[^ -~]',b'',t).decode()
        import re as r2
        # extract text between parentheses (PDF text ops)
        parts=r2.findall(r'\((.*?)\)', txt)
        if parts: print(' '.join(parts))
    except Exception: pass
")"}

